import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer
from src.events import Recorder


def setup():
    c = sqlite3.connect(":memory:")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c


def state(c):
    return (balance(c, "a"), balance(c, "b"),
            c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0])


# invalid transfers
for args in [("a", "a", 1), ("a", "x", 1), ("x", "a", 1), ("a", "b", 0),
             ("a", "b", -5), ("a", "b", True), ("a", "b", 1.0), ("a", "b", "1"),
             ("a", "b", 101)]:
    c, p = setup(), Recorder()
    try:
        transfer(c, p, *args)
    except ValueError:
        pass
    else:
        raise AssertionError(args)
    assert state(c) == (100, 20, 0) and p.events == [] and not c.in_transaction, args

# full balance ok
c, p = setup(), Recorder()
transfer(c, p, "a", "b", 100)
assert state(c) == (0, 120, 1)


# database failure at each statement and at commit
class Flaky:
    def __init__(self, inner, fail_write=None, fail_commit=False):
        self.inner, self.fail_write, self.fail_commit, self.writes = inner, fail_write, fail_commit, 0

    def execute(self, sql, params=()):
        if not sql.lstrip().upper().startswith("SELECT"):
            self.writes += 1
            if self.writes == self.fail_write:
                raise sqlite3.OperationalError("boom")
        return self.inner.execute(sql, params)

    def commit(self):
        if self.fail_commit:
            raise sqlite3.OperationalError("commit boom")
        self.inner.commit()

    def rollback(self):
        self.inner.rollback()


for kw in [dict(fail_write=1), dict(fail_write=2), dict(fail_write=3), dict(fail_commit=True)]:
    c, p = setup(), Recorder()
    try:
        transfer(Flaky(c, **kw), p, "a", "b", 10)
    except sqlite3.OperationalError:
        pass
    else:
        raise AssertionError(kw)
    assert state(c) == (100, 20, 0) and p.events == [] and not c.in_transaction, kw


# publication failure propagates, transfer stays committed
class Broken:
    def publish(self, event):
        raise RuntimeError("down")


c = setup()
try:
    transfer(c, Broken(), "a", "b", 10)
except RuntimeError:
    pass
else:
    raise AssertionError("publish error swallowed")
assert state(c) == (90, 30, 1) and not c.in_transaction
c.rollback()
assert state(c) == (90, 30, 1)
print("ok")

